export async function resolveHermesModelProvider(config: Record<string, unknown>) {
  const model = cfgString(config.model) || DEFAULT_MODEL;
  const configuredProvider = cfgString(config.provider);
  if (configuredProvider && !(VALID_PROVIDERS as readonly string[]).includes(configuredProvider)) return { model, resolvedProvider: "auto", resolvedFrom: "invalid", providerInvalid: true };
  let detectedConfig: Awaited<ReturnType<typeof detectModel>> | null = null;
  const explicitProvider = cfgString(config.provider);

  if (!explicitProvider) {
    try {
      detectedConfig = await detectModel();
    } catch {
      // Non-fatal — detection failure shouldn't block execution
    }
  }

  const { provider: resolvedProvider, resolvedFrom } = resolveProvider({
    explicitProvider,
    detectedProvider: detectedConfig?.provider,
    detectedModel: detectedConfig?.model,
    detectedBaseUrl: detectedConfig?.baseUrl,
    detectedHasApiKey: detectedConfig?.hasApiKey,
    detectedApiMode: detectedConfig?.apiMode,
    model,
  });

  return { model, resolvedProvider, resolvedFrom, providerInvalid: false };
}

export function buildHermesBaseEnv(config: Record<string, unknown>): Record<string, string> {
  const configured = typeof config.env === "object" && config.env !== null ? config.env as Record<string, unknown> : {};
  const env = Object.fromEntries(Object.entries({ ...process.env, ...configured }).filter((entry): entry is [string, string] => typeof entry[1] === "string"));
  delete env.PAPERCLIP_API_KEY;
  delete env.PAPERCLIP_WAKE_PAYLOAD_JSON;
  return env;
}

